window.DATA = {"exo": {"EX1": {"id": "EX1", "titre": "Diagnostiquer son style de communication", "mode": "Individuel", "duree": 8, "chap": "Carnet · chapitre 1", "situation": ["Notez chaque affirmation de 1 (pas du tout d'accord) à 4 (tout à fait d'accord).", "A. Direct / Nuancé", "1. Je dis franchement ce que je pense, même si cela peut déplaire.", "2. En réunion, je donne mon avis en premier plutôt que d'attendre.", "3. Je préfère une réponse courte et claire à un long développement.", "4. Quand je ne suis pas d'accord, je le dis tout de suite.", "B. Tâche / Relation", "5. Avant de parler d'un problème, je prends des nouvelles de la personne.", "6. Je repère vite l'ambiance et l'état d'esprit d'une équipe.", "7. Je préfère régler un désaccord à l'oral plutôt que par document.", "8. J'explique le contexte, pas seulement la consigne."], "taches": ["Additionnez les points A (affirmations 1 à 4) puis B (5 à 8).", "Placez-vous sur la grille : A de 11 à 16 = Direct, de 4 à 10 = Nuancé ; B de 11 à 16 = Relation, de 4 à 10 = Tâche. Le croisement donne votre profil.", "Lisez votre profil (force, risque, conseil) sur la correction.", "Comparez avec votre voisin : sur quelle situation vos styles se heurteraient-ils ?", "Appliquez : à quel personnage de TransLor (Marc, Paul, Sonia, la directrice) ressemblez-vous le plus ?"], "livrable": "Votre profil et un point d'attention, à noter dans le carnet (chapitre 1).", "corr": {"methode": ["Calculer A (4 à 16) et B (4 à 16).", "Direct si A ≥ 11, sinon Nuancé ; Relation si B ≥ 11, sinon Tâche.", "Lire la ligne du profil : force, risque, conseil.", "Se rappeler : aucun profil n'est meilleur, le piège est de parler à tout le monde comme à soi."], "cols": ["Profil", "Force", "Risque en entreprise", "Conseil"], "widths": [1.4, 2, 2.6, 2.6], "rows": [["Décideur\nDirect + Tâche", "Clarté, rapidité", "Paraît brusque, oublie le contexte", "Ajouter une phrase de contexte"], ["Animateur\nDirect + Relation", "Énergie, lien", "Dilue le message dans l'ambiance", "Finir par une demande précise"], ["Analyste\nNuancé + Tâche", "Rigueur, précision", "Trop long, décision retardée", "Donner la conclusion d'abord"], ["Facilitateur\nNuancé + Relation", "Écoute, consensus", "Évite le désaccord nécessaire", "Oser dire non avec une alternative"]], "erreurs": ["Se noter selon l'image que l'on voudrait donner plutôt que selon ses réactions réelles.", "Croire que le test mesure la personnalité : c'est un modèle pédagogique simplifié, pas un outil de recrutement.", "Sur TransLor : Marc (Décideur) écrit court ; Paul (Facilitateur) peut lire ses messages comme brusques. Le problème est l'écart, pas le style."]}}, "EX2": {"id": "EX2", "titre": "Chiffrer le coût de la non-communication", "mode": "Binôme", "duree": 12, "chap": "Carnet · chapitre 1", "situation": ["TransLor : 120 salariés, 14 M€ de chiffre d'affaires, marge d'environ 280 k€ (2 %).", "Hypothèses pédagogiques (inventées) : chaque salarié perd en moyenne 1,5 h par semaine en précisions, reprises et messages inutiles ; 45 semaines travaillées ; coût horaire chargé moyen 32 €.", "Un plan de communication (une journée de formation par salarié, 7 h, plus 6 000 € de prestation) pourrait réduire cette perte de 40 %."], "taches": ["Calculez les heures perdues par an.", "Calculez le coût annuel.", "Exprimez-le en % du chiffre d'affaires puis en % de la marge.", "Calculez le gain annuel si la perte baisse de 40 %.", "Calculez le coût du plan, le ROI de la première année et le délai de retour en mois.", "Refaites le calcul avec une décote de 50 % sur le gain (prudence). Que décidez-vous ?"], "livrable": "Un tableau de calcul ligne par ligne et une recommandation en deux phrases.", "corr": {"methode": ["Heures = salariés × h/semaine × semaines.", "Coût = heures × coût horaire.", "Rapporter au CA (14 M€) et à la marge (280 k€).", "Gain = coût × 40 %. Coût du plan = 120 × 7 h × 32 € + 6 000 €.", "ROI = (gain − coût) / coût ; retour (mois) = coût / gain × 12."], "rows": [["Heures perdues par an", "120 × 1,5 × 45 = 8 100 h"], ["Coût annuel", "8 100 × 32 = 259 200 €"], ["En % du CA et de la marge", "259 200 / 14 000 000 = 1,85 % du CA ; 259 200 / 280 000 = 92,6 % de la marge"], ["Gain à −40 %", "259 200 × 0,40 = 103 680 €"], ["Coût du plan, ROI, retour", "120 × 7 × 32 = 26 880 ; + 6 000 = 32 880 € ; ROI = 70 800 / 32 880 = 215 % ; retour 32 880 / 103 680 × 12 = 3,8 mois"], ["Avec décote de 50 %", "Gain 51 840 € ; ROI = 18 960 / 32 880 = 57,7 % ; retour 7,6 mois → reste rentable : on lance le plan"]], "erreurs": ["Oublier le coût de présence des salariés en formation (26 880 €), qui est le plus gros poste du plan.", "Présenter 259 200 € comme un fait : ce sont des hypothèses inventées. Toujours annoncer les hypothèses et tester une version prudente.", "Confondre ROI (215 %) et délai de retour (3,8 mois)."]}}, "EX3": {"id": "EX3", "titre": "Analyser un échange raté entre exploitation et informatique", "mode": "Binôme", "duree": 10, "chap": "Carnet · chapitre 1", "situation": ["Messagerie interne de TransLor, entre Marc (gestionnaire d'exploitation) et l'administrateur système :", "Lundi 8 h 10, Marc : « Le TMS est lent, il faut régler ça vite. »", "Lundi 8 h 40, Admin : « OK, je regarde. »", "Jeudi 9 h 05, Marc : « Toujours rien ! Mes gars perdent un temps fou. »", "Jeudi 9 h 30, Admin : « J'ai ajouté de la mémoire au serveur, c'est fait. »", "Jeudi 9 h 45, Marc : « Mais c'est l'écran des tournées qui rame, vers 7 h, pas le serveur… »"], "taches": ["Pour chaque message, notez ce qui manque (quoi, où, quand, combien, pour quand).", "Nommez le type de bruit en cause (technique, sémantique, psychologique, organisationnel).", "Retrouvez le vrai problème tel que Marc le décrit.", "Quelle question de clarification l'administrateur aurait-il dû poser dès lundi ?", "Réécrivez le message initial de Marc en 4 lignes, conclusion d'abord."], "livrable": "Le message de Marc réécrit et la question de clarification de l'administrateur.", "corr": {"methode": ["Relire chaque message avec les 5 questions : quoi, où, quand, combien, pour quand.", "Repérer les mots flous (« lent », « vite », « je regarde »).", "Chercher quelle solution a été choisie avant le diagnostic.", "Réécrire : conclusion, impact, attendu, échéance."], "rows": [["Ce qui manque", "« lent » : quelle fonction, quand, combien de secondes ? « vite » : pour quand ? « je regarde » : aucun retour promis"], ["Bruit en cause", "Sémantique (mots flous), organisationnel (pas de ticket), psychologique (agacement croissant)"], ["Vrai problème", "L'écran Tournées ralentit autour de 7 h (pic de connexions) ; l'ajout de mémoire du serveur répondait à une autre question"], ["Question de clarification", "« Quelle fonction est lente, à quelle heure, et combien de temps cela dure-t-il ? Qu'est-ce qui serait acceptable ? »"], ["Cause racine de l'échec", "Solution choisie avant le diagnostic, sans critère de réussite partagé"]], "erreurs": ["Chercher un coupable (Marc trop vague ou l'admin trop passif) : les deux ont une part, le système n'imposait aucune précision.", "Proposer « plus de réunions » : il fallait un ticket avec impact et critère de réussite.", "Oublier de rappeler la date de retour : « je regarde » sans échéance équivaut à « je ne m'engage pas »."], "modele": "Objet : TMS – écran Tournées : 25 s de chargement entre 6 h 45 et 7 h 30\n\nMarc, à l'administrateur : « L'écran Tournées met environ 25 secondes à s'ouvrir entre 6 h 45 et 7 h 30, pour les 15 gestionnaires. Les départs sont retardés d'environ 10 minutes. J'attends moins de 5 secondes. Pouvez-vous me proposer un diagnostic d'ici jeudi ? Je suis disponible à 7 h pour reproduire le problème. »\n\n(Valeurs 25 s et 10 min inventées pour l'exemple.)", "retenir": "Un message utile contient : conclusion, impact chiffré, attendu mesurable, échéance."}}, "EX4": {"id": "EX4", "titre": "Reformuler : écho, clarification, synthèse, reflet", "mode": "Binôme", "duree": 10, "chap": "Carnet · chapitre 2", "situation": ["Six phrases entendues chez TransLor. Pour chacune, écrivez une reformulation de 15 mots maximum et nommez son type.", "1. Marc : « Je n'en peux plus de ces tableaux Excel. »", "2. Léa : « La tablette plante dès que j'arrive à l'entrepôt. »", "3. La directrice : « Il me faut une solution pour le dernier kilomètre avant l'été, sans exploser le budget. »", "4. Sonia : « Les factures arrivent toujours en retard, je ne peux pas clôturer. »", "5. Paul : « Les conducteurs sont démotivés, on devrait tout revoir. »", "6. Léa : « Franchement, on ne nous écoute jamais. »"], "taches": ["Rappel des types : écho (répéter l'essentiel), clarification (préciser), synthèse (regrouper), reflet (nommer l'émotion).", "Écrivez votre reformulation pour chaque phrase.", "Nommez le type utilisé.", "Soulignez, dans vos reformulations, tout conseil ou jugement caché, et retirez-le.", "Choisissez la phrase la plus risquée et dites pourquoi."], "livrable": "Six reformulations, chacune avec son type.", "corr": {"methode": ["Repérer le fait et l'émotion dans la phrase.", "Choisir le type : écho, clarification, synthèse ou reflet.", "Redire avec ses mots, sans conseil ni jugement.", "Terminer par une invitation à confirmer ou à préciser."], "cols": ["Phrase", "Type conseillé", "Exemple de reformulation"], "widths": [0.8, 1.5, 4.6], "rows": [["1", "Reflet", "« Cette saisie manuelle vous épuise ? »"], ["2", "Écho + clarification", "« Elle plante à l'arrivée à l'entrepôt : à chaque fois ? »"], ["3", "Synthèse", "« Deux contraintes : avant l'été et budget maîtrisé. Laquelle prime si on doit choisir ? »"], ["4", "Reflet + clarification", "« Le retard bloque votre clôture. De qui dépendent ces factures ? »"], ["5", "Clarification", "« Qu'avez-vous observé qui vous fait dire qu'ils sont démotivés ? »"], ["6", "Reflet", "« Vous avez le sentiment de ne pas être entendue. Sur quel sujet récemment ? »"]], "erreurs": ["Répéter mot à mot : cela ressemble à un écho de perroquet et n'apporte rien.", "Glisser un conseil : « Vous devriez demander une tablette neuve ».", "Reformuler en changeant le sens : la phrase 5 est un jugement de Paul, pas un fait ; la clarification demande les faits."]}}, "EX5": {"id": "EX5", "titre": "Triades d'écoute : parleur, écouteur, observateur", "mode": "Groupe de 3", "duree": 18, "chap": "Carnet · chapitre 2", "situation": ["Trois manches de 6 minutes : 3 min d'entretien, 2 min de retour, 1 min de changement de rôle. Chacun joue les trois rôles.", "Parleur : raconte une situation professionnelle réelle et non confidentielle (ou le cas de Léa : « la tablette plante et on ne m'écoute pas »).", "Écouteur : n'a le droit qu'aux reformulations et aux questions ouvertes. Aucun conseil, aucune histoire personnelle.", "Observateur : note les comportements sur la grille (chronomètre, silences, reformulations, questions, conseils)."], "taches": ["Parleur : exposez la situation en 1 minute, puis répondez.", "Écouteur : faites au moins 3 reformulations et 2 questions ouvertes.", "Observateur : remplissez la grille d'observation.", "Retour en 3 minutes : l'observateur parle d'abord, puis le parleur dit ce qui l'a aidé.", "Notez un geste d'écoute à conserver et un à abandonner."], "livrable": "La grille d'observation remplie pour chaque manche.", "corr": {"methode": ["L'observateur compte, ne juge pas.", "Le parleur dit ce qui l'a aidé avant tout commentaire.", "L'écouteur se corrige sur un seul point à la fois.", "Chacun note un engagement concret dans le carnet."], "cols": ["Critère observé", "Cible", "Comment le noter"], "widths": [2.5, 1.2, 4.3], "rows": [["Temps de parole de l'écouteur", "moins de 30 %", "Chronomètre : secondes de parole / 180"], ["Reformulations", "3 ou plus", "Un trait par reformulation réussie, sans conseil"], ["Questions ouvertes", "2 ou plus", "« Comment », « Qu'est-ce que », « Raconte-moi »"], ["Conseils ou jugements", "0", "Un trait par « tu devrais », « moi à ta place »"], ["Silence toléré", "au moins 3 s une fois", "L'écouteur laisse un blanc sans le combler"], ["Synthèse finale", "oui", "Résumé en une phrase validé par le parleur"]], "erreurs": ["Remplir les silences : le parleur n'a pas le temps de creuser.", "Raconter « moi aussi » : l'attention passe de l'autre à soi.", "Observateur qui intervient pendant l'entretien : il note, il ne parle pas."]}}, "EX6": {"id": "EX6", "titre": "Recueillir un besoin : l'entretien avec Marc", "mode": "Binôme (enquêteur / Marc)", "duree": 15, "chap": "Carnet · chapitre 2", "situation": ["Marc, gestionnaire d'exploitation, vous dit : « Je voudrais un export Excel des tournées du jour. »", "Vous êtes l'ingénieur chargé d'étudier la demande. Votre binôme joue Marc (sa fiche de rôle est sur l'application, à ne pas montrer à l'enquêteur).", "Vous avez 8 minutes. Ne proposez aucune solution avant d'avoir compris le besoin."], "taches": ["Préparez 6 questions en entonnoir : large, puis précis, puis de confirmation.", "Menez l'entretien (8 minutes).", "Reformulez le besoin réel en une phrase.", "Chiffrez le coût actuel : 45 min par jour et par gestionnaire, 225 jours, 15 gestionnaires, 32 € de l'heure.", "Faites valider par Marc le critère de réussite."], "livrable": "Besoin reformulé, coût annuel, critère de réussite.", "fiche_role": "FICHE DE MARC (secrète). Demande affichée : un export Excel des tournées. Besoin réel : savoir avant 7 h quelles tournées risquent un retard pour prévenir les clients. À dévoiler seulement si l'enquêteur pose des questions ouvertes : 20 tournées par jour, 12 % dépassent le créneau, il recopie les heures dans Excel 45 minutes par jour, 3 clients (60 % du CA) pénalisent les retards, budget maximal 2 k€, critère de réussite : une alerte au moins 30 minutes avant le créneau. Si on vous propose une solution trop vite, répondez « oui, peut-être ».", "corr": {"methode": ["Questions larges : « Racontez-moi une matinée type ». Puis précises : fréquence, durée, impact.", "Demander à quoi servira l'export (le besoin derrière la solution).", "Reformuler en une phrase besoin + critère.", "Chiffrer l'impact avant de proposer."], "rows": [["Besoin réel", "Voir avant 7 h les tournées à risque de retard, pour prévenir les clients à temps"], ["Fréquence du problème", "20 tournées × 12 % = 2,4 tournées en retard par jour ; 2,4 × 225 = 540 par an"], ["Coût actuel de la ressaisie", "0,75 h × 225 j × 32 € = 5 400 € par gestionnaire ; × 15 = 81 000 € par an"], ["Critère de réussite", "Alerte au moins 30 minutes avant le créneau, budget ≤ 2 k€"], ["Phrase de reformulation", "« Vous voulez être alerté 30 minutes avant un retard probable pour prévenir vos clients, sans ressaisie ; l'export n'est qu'un moyen. »"]], "erreurs": ["Proposer « on vous fait un export » dès la première minute : la solution précède le besoin.", "Enchaîner des questions fermées : on obtient oui ou non, pas le contexte.", "Oublier de chiffrer : sans 81 000 €, la demande ne passe pas l'arbitrage du budget."]}}, "EX7": {"id": "EX7", "titre": "Reconnaître les quatre comportements", "mode": "Binôme", "duree": 8, "chap": "Carnet · chapitre 3", "situation": ["Classez chaque phrase : passif, agressif, manipulateur ou assertif.", "1. « Bon, d'accord, je m'en occupe… (soupir) comme d'habitude. »", "2. « Encore un retard ! Vous ne servez à rien ! »", "3. « Je ne peux pas livrer demain, mais vendredi à 12 h. Qu'en pensez-vous ? »", "4. « Oh, ce n'est pas grave, ne vous inquiétez pas pour moi. » (alors qu'il y a un vrai problème)", "5. « Tout le monde pense que ton code est mauvais. »", "6. « Si tu m'appréciais, tu prendrais mon astreinte. »"], "taches": ["Classez les 6 phrases.", "Justifiez chaque classement par un indice (ton, généralisation, reproche, chantage…).", "Réécrivez les phrases 2 et 5 en version assertive.", "Identifiez votre comportement par défaut quand vous êtes sous pression.", "Citez une situation de TransLor où vous seriez tenté par l'un des trois comportements non assertifs."], "livrable": "Le tableau de classement et deux phrases réécrites.", "corr": {"methode": ["Chercher qui est respecté : moi, l'autre, ou les deux ?", "Repérer les mots absolus (« toujours », « jamais », « tout le monde »).", "L'assertif décrit un fait, exprime un besoin et propose.", "Réécrire sans jugement sur la personne."], "cols": ["Phrase", "Comportement", "Indice", "Version assertive"], "widths": [0.6, 1.4, 2.4, 3.6], "rows": [["1", "Manipulateur (passif-agressif)", "Accord de façade + reproche indirect", "« Je peux le faire cette semaine ; la prochaine fois, partageons-nous la charge. »"], ["2", "Agressif", "Jugement sur les personnes, généralisation", "« Ce colis est arrivé avec 2 h de retard. Je veux comprendre pourquoi. »"], ["3", "Assertif", "Fait, limite, alternative, question", "—"], ["4", "Passif", "Nie son besoin pour éviter le conflit", "« Si, c'est un souci : j'ai besoin de… »"], ["5", "Agressif / manipulateur", "Appel au « tout le monde », jugement", "« Dans cette revue, j'ai relevé trois fonctions sans test. Peux-tu en ajouter ? »"], ["6", "Manipulateur", "Chantage affectif", "« Peux-tu prendre mon astreinte ? Je te rends la pareille le mois prochain. »"]], "erreurs": ["Confondre assertif et poli : on peut être très poli et passif-agressif.", "Prendre « tout le monde pense » pour un fait : c'est une pression sociale.", "Croire que l'assertivité impose d'obtenir gain de cause : elle garantit d'être clair et respectueux, pas d'avoir raison."]}}, "EX8": {"id": "EX8", "titre": "Six situations : DESC, SBI ou « oui, si… » ?", "mode": "Groupe de 3", "duree": 20, "chap": "Carnet · chapitre 3", "situation": ["Pour chaque situation, choisissez la méthode (DESC : décrire, exprimer, spécifier, conséquences ; SBI : situation, comportement, impact ; « oui, si… ») et écrivez la phrase clé.", "1. Revue de code : un collègue a écrit « code illisible » sur votre demande de fusion.", "2. Un collègue livre en retard pour la 3e fois ; votre propre livraison est bloquée.", "3. La directrice demande une démo pour demain, alors que l'équipe est à 100 % de charge.", "4. Un client appelle, furieux : sa livraison est partie à la mauvaise adresse.", "5. Un collègue vous coupe la parole en réunion.", "6. Le prestataire du TMS livre la mise à jour avec 3 jours de retard."], "taches": ["Choisissez la méthode pour chaque situation.", "Écrivez la phrase clé (30 mots maximum).", "Vérifiez qu'elle contient un fait observable et pas un jugement.", "Choisissez la situation la plus délicate et dites quel canal (oral, écrit) convient.", "Jouez la situation 5 à deux, 1 minute."], "livrable": "Un tableau situation, méthode, phrase clé.", "corr": {"methode": ["Situation entre pairs sur un comportement : SBI ou DESC.", "Demande qui dépasse la capacité : « oui, si… » avec alternatives.", "Client en colère : écouter, reformuler, puis proposer.", "Relire : aucun adjectif sur la personne."], "cols": ["Situation", "Méthode", "Phrase clé"], "widths": [0.7, 1.3, 6.3], "rows": [["1", "SBI", "« Dans ma demande de fusion de ce matin, ton commentaire « illisible » ne m'indique pas quoi changer ; peux-tu citer les lignes concernées ? »"], ["2", "DESC", "« Trois livraisons ont dépassé la date. Je suis bloqué sur ma partie. Peux-tu me donner une date ferme ? Sinon, je préviens le chef de projet vendredi. »"], ["3", "Oui, si…", "« Oui pour une démo demain si nous retirons la fonction B ; sinon je propose jeudi pour la version complète. »"], ["4", "Écoute puis solution", "« Votre colis est parti à la mauvaise adresse, c'est inacceptable. Je confirme : adresse, heure. Je rappelle dans 30 minutes avec une solution. »"], ["5", "SBI immédiat", "« Je n'avais pas fini ma phrase. Je termine, puis je te laisse la parole. »"], ["6", "DESC écrit", "« La mise à jour devait arriver lundi et arrive jeudi, ce qui retarde nos tests. Nous attendons un planning révisé d'ici demain. »"]], "erreurs": ["Écrire « il est toujours en retard » : jugement, pas comportement.", "Dire non sans alternative à la directrice : la relation se tend et la décision se retarde.", "Régler par écrit une situation émotionnelle (4) : décrocher d'abord, confirmer par écrit ensuite."]}}, "F1": {"id": "F1", "titre": "Flash · Vrai ou faux sur la communication", "mode": "Solo puis voisin", "duree": 5, "chap": "Carnet · chapitre 1", "situation": ["1. 93 % du message passe par le non-verbal.", "2. Un silence peut être une réponse.", "3. Le récepteur décode toujours le message comme l'émetteur l'a encodé.", "4. Le feedback ferme la boucle de communication.", "5. Pour un désaccord chargé d'émotion, un e-mail est plus sûr qu'un appel."], "taches": ["Répondez Vrai ou Faux pour chaque affirmation.", "Justifiez en une phrase.", "Citez un exemple chez TransLor pour l'affirmation 3."], "livrable": "", "corr": {"methode": ["Séparer ce qui est établi de ce qui est un mythe.", "Penser à un exemple concret."], "rows": [["1", "Faux : les 7 % / 38 % / 55 % de Mehrabian portent sur des messages de sentiments incohérents en laboratoire, pas sur toute communication."], ["2", "Vrai : le silence est un signal (accord, désaccord, réflexion) à vérifier par une question."], ["3", "Faux : le décodage dépend du cadre de référence ; d'où le feedback."], ["4", "Vrai : sans retour, l'émetteur ignore ce qui a été compris."], ["5", "Faux : l'écrit supprime le ton et amplifie les malentendus ; on appelle d'abord, on confirme ensuite par écrit."]], "erreurs": ["Retenir « 93 % non-verbal » : chiffre souvent cité hors contexte."]}}, "F2": {"id": "F2", "titre": "Flash · Questions ouvertes, fermées ou biaisées ?", "mode": "Binôme", "duree": 5, "chap": "Carnet · chapitre 2", "situation": ["a. « Pourquoi n'avez-vous pas fait la saisie ? »", "b. « Peux-tu me décrire une tournée type ? »", "c. « Le retard vient-il du chargement ? »", "d. « Combien de temps cela prend-il ? »", "e. « Vous êtes d'accord, non ? »", "f. « Qu'est-ce qui serait un bon résultat pour toi ? »"], "taches": ["Classez chaque question : ouverte, fermée ou biaisée (suggestive ou accusatoire).", "Réécrivez a et e en questions neutres.", "Gardez les deux meilleures pour un entretien de recueil de besoin."], "livrable": "", "corr": {"methode": ["Ouverte : appelle un développement. Fermée : oui, non ou un chiffre.", "Biaisée : suggère la réponse ou contient un reproche."], "rows": [["a", "Ouverte mais accusatoire : « Qu'est-ce qui a empêché la saisie ? »"], ["b", "Ouverte : excellente pour démarrer"], ["c", "Fermée : utile pour vérifier une hypothèse"], ["d", "Fermée chiffrée : utile pour quantifier"], ["e", "Biaisée (suggestive) : « Qu'en pensez-vous ? »"], ["f", "Ouverte : fait émerger le critère de réussite"]], "erreurs": ["Abuser des « pourquoi », perçus comme un reproche.", "Rester sur des questions fermées : on confirme ses hypothèses au lieu de découvrir le besoin."]}}, "F3": {"id": "F3", "titre": "Flash · Fait observable ou jugement ?", "mode": "Solo puis voisin", "duree": 4, "chap": "Carnet · chapitre 3", "situation": ["1. « Tu es négligent. »", "2. « Hier, tu as livré sans scanner trois colis. »", "3. « Tu fais mal ton travail. »", "4. « En réunion de 9 h, tu as coupé la parole à Sonia deux fois. »", "5. « Tu te moques des délais. »"], "taches": ["Marquez F (fait observable) ou J (jugement).", "Transformez chaque jugement en fait observable (SBI : situation, comportement)."], "livrable": "", "corr": {"methode": ["Un fait se filme : on peut le voir ou le mesurer.", "Un jugement qualifie la personne."], "rows": [["1", "J → « Lundi, le chargement n'a pas été vérifié sur deux palettes. »"], ["2", "F : date, action, quantité"], ["3", "J → « Cette fonction n'est pas testée. »"], ["4", "F : lieu, moment, nombre de fois"], ["5", "J → « Les trois dernières livraisons ont dépassé la date prévue. »"]], "erreurs": ["Croire qu'un adjectif est un fait : « négligent » ne se filme pas."]}}, "EX9": {"id": "EX9", "titre": "Dire non à la directrice : « oui, si… »", "mode": "Binôme", "duree": 12, "chap": "Carnet · chapitre 3", "situation": ["La directrice vous écrit : « Je veux le suivi des colis en temps réel pour notre client le plus important, dès demain. »", "Données : l'équipe informatique a 10 jours-homme disponibles ce mois-ci, dont 8 déjà engagés sur la migration du TMS. La demande représente environ 6 jours-homme."], "taches": ["Calculez la capacité disponible et le manque.", "Listez trois options (oui si, version réduite, nouveau délai) avec leur coût en jours-homme.", "Rédigez la réponse à la directrice en 5 lignes, décision proposée d'abord.", "Choisissez le canal (appel, e-mail) et justifiez.", "Quelle contrepartie demandez-vous à la direction ?"], "livrable": "Une réponse écrite de 5 lignes.", "corr": {"methode": ["Capacité disponible = capacité − engagements.", "Écart = demande − capacité disponible.", "Proposer des alternatives chiffrées, jamais un non sec.", "Mettre la décision d'abord, la contrainte ensuite."], "rows": [["Capacité disponible", "10 − 8 = 2 jours-homme"], ["Manque", "6 − 2 = 4 jours-homme"], ["Option 1 : oui, si", "Oui si la migration du TMS est décalée de 4 j-h (coût : migration retardée d'une semaine)"], ["Option 2 : version réduite", "2 j-h : alerte SMS de retard, sans suivi en temps réel complet"], ["Option 3 : délai", "Livrer la version complète dans 3 semaines, une fois la migration terminée"], ["Canal", "Appel puis e-mail de confirmation : la direction attend une décision, l'écrit garde la trace"]], "erreurs": ["Répondre « impossible » : la directrice cherche des options, pas un refus.", "Oublier de chiffrer les options en jours-homme : sans chiffre, l'arbitrage est impossible.", "Dire oui puis subir : un oui sans condition crée la dette de délai."], "modele": "« Bonjour, je vous propose de livrer demain une alerte SMS de retard (2 jours-homme, dans notre capacité) et la version complète dans 3 semaines, après la migration du TMS. La version complète demain exigerait de retarder la migration d'une semaine (4 jours-homme manquants). Quel arbitrage préférez-vous ? Je vous appelle à 14 h pour en discuter. »", "retenir": "« Oui, si… » : une décision proposée, des options chiffrées, une question d'arbitrage."}}, "EX10": {"id": "EX10", "titre": "Réécrire quatre messages de messagerie instantanée", "mode": "Individuel", "duree": 8, "chap": "Carnet · chapitre 4", "situation": ["Messages réellement envoyés (reconstitués) dans l'équipe de TransLor :", "1. « Ça marche pas. »", "2. « URGENT !!! Appelle-moi. »", "3. « Tu as vu mon mail ? »", "4. « Je ne suis pas d'accord. »"], "taches": ["Pour chaque message, identifiez ce qui manque.", "Réécrivez-le en 2 phrases maximum.", "Précisez le canal le plus adapté.", "Vérifiez que l'autre peut agir sans vous poser de question.", "Appliquez à un message de votre messagerie récente."], "livrable": "Quatre messages réécrits.", "corr": {"methode": ["Qui, quoi, où, quand, pour quand ?", "Mettre la demande en premier.", "Donner de quoi agir sans question supplémentaire."], "cols": ["Avant", "Défaut", "Après"], "widths": [1.6, 2.2, 4.6], "rows": [["« Ça marche pas. »", "Aucun objet, aucun contexte", "« L'application Tablette affiche l'erreur 504 depuis 6 h 40 sur 14 tablettes. Peux-tu regarder avant 8 h ? »"], ["« URGENT !!! Appelle-moi. »", "Anxiogène, sans raison", "« Un client conteste une livraison à 14 h. Peux-tu m'appeler avant 13 h 30 ? »"], ["« Tu as vu mon mail ? »", "Relance sans contenu", "« Pour la décision sur le transporteur, j'attends ton choix d'ici jeudi 12 h. »"], ["« Je ne suis pas d'accord. »", "Désaccord sans raison ni piste", "« Je ne vois pas comment tenir la date de vendredi. Que penses-tu de jeudi de la semaine prochaine ? »"]], "erreurs": ["Écrire « URGENT » sans dire pourquoi ni pour quand.", "Multiplier les points d'exclamation : le ton se lit comme de l'agressivité.", "Prendre une décision importante en message privé, sans trace partagée."]}}, "EX11": {"id": "EX11", "titre": "Corriger trois e-mails : avant / après", "mode": "Binôme", "duree": 10, "chap": "Carnet · chapitre 4", "situation": ["E1 (à la directrice) — Objet : « Question ». Corps : « Bonjour, j'ai réfléchi au sujet dont on a parlé, je pense qu'on pourrait faire autrement mais je ne sais pas si c'est possible, qu'en pensez-vous ? »", "E2 (à Marc) — Objet : « Re: Re: Re: Fwd: tournées ». Corps : trois sujets mélangés (planning de lundi, tablette de Léa, facture du carburant), aucune demande claire.", "E3 (à 40 personnes, « Répondre à tous ») : « OK merci ! »"], "taches": ["Repérez pour chaque e-mail trois défauts.", "Réécrivez l'objet de E1 et E2 (8 mots maximum).", "Réécrivez le corps de E1 en 4 lignes : conclusion d'abord.", "Que faites-vous de E2 : un e-mail ou trois ?", "Que dites-vous à la personne qui envoie E3 ?"], "livrable": "Trois e-mails corrigés.", "corr": {"methode": ["Objet = sujet + action attendue.", "Un e-mail = un sujet.", "Conclusion d'abord, détails ensuite.", "Répondre à tous seulement si tous doivent le savoir."], "rows": [["E1 : défauts", "Objet vide ; idée vague (« autrement ») ; pas d'action ni d'échéance"], ["E1 : objet", "« Décision avant jeudi : changer l'ordre des tournées ? »"], ["E1 : corps", "« Je propose d'inverser les tournées 3 et 4 pour gagner 20 minutes. Votre accord est nécessaire avant jeudi 12 h. Contexte : deux retards cette semaine. Je vous détaille en annexe. »"], ["E2 : traitement", "Trois e-mails séparés, chacun avec son objet : « Planning lundi : validation », « Tablette Léa : panne », « Facture carburant : justificatif »"], ["E3 : conseil", "Ne pas répondre à tous ; pour remercier, utiliser une réaction ou répondre à l'expéditeur seul"]], "erreurs": ["Laisser un fil « Re: Re: Fwd » qui ne reflète plus le sujet.", "Mettre la demande à la fin d'un long paragraphe.", "Aucune échéance : la demande n'est jamais traitée."]}}, "EX12": {"id": "EX12", "titre": "À / Cc / Cci, ton et droit à la déconnexion", "mode": "Binôme", "duree": 8, "chap": "Carnet · chapitre 4", "situation": ["E4 — Un développeur écrit à un client : « Salut, ton problème est réglé, c'était la faute de ton prestataire. » ; il met en copie toute l'équipe commerciale, et en copie cachée (Cci) son chef.", "E5 — Un chef de projet envoie à 22 h 15 à un collaborateur : « Il me faut ça demain 8 h, merci. »"], "taches": ["Pour E4 : relevez les problèmes de ton, de Cc et de Cci.", "Réécrivez E4 en trois phrases, vouvoiement.", "Pour E5 : quel est le problème ? Que proposer ?", "Rappelez la règle sur le droit à la déconnexion (cadre légal à vérifier).", "Écrivez la règle de messagerie que vous proposez pour TransLor."], "livrable": "Deux messages corrigés et une règle d'équipe.", "corr": {"methode": ["À = qui agit ; Cc = qui doit savoir ; Cci = exception, jamais pour surveiller.", "Faire descendre le ton d'un cran vers le neutre.", "Envoi différé pour respecter les horaires d'autrui."], "rows": [["E4 : problèmes", "Tutoiement avec un client ; reproche à un tiers ; Cc inutile (toute l'équipe) ; Cci d'un chef = défiance"], ["E4 : version corrigée", "« Bonjour Madame, le problème est résolu depuis 15 h. Il venait d'un paramétrage que nous avons corrigé. Nous restons disponibles. »"], ["E5 : problème", "Demande hors horaires, délai court : pression implicite"], ["E5 : solution", "Programmer l'envoi à 8 h 00 et demander une réponse avant 17 h"], ["Cadre légal", "Droit à la déconnexion : les modalités se négocient dans l'entreprise (Code du travail, art. L2242-17 — à vérifier)"], ["Règle TransLor", "Pas d'attente de réponse entre 19 h et 7 h 30 ; urgence = appel, pas message"]], "erreurs": ["Utiliser Cci pour « se couvrir » : si un chef doit savoir, il va en Cc.", "Penser que « urgent » justifie un envoi nocturne : prévoir un canal d'astreinte.", "Citer un article de loi de mémoire : toujours vérifier avant diffusion."]}}, "EX13": {"id": "EX13", "titre": "Rédiger un compte rendu de réunion", "mode": "Groupe de 3", "duree": 12, "chap": "Carnet · chapitre 4", "situation": ["Notes brutes de la réunion « Dernier kilomètre » (9 personnes, 6 juin) :", "Directrice : lancement visé en septembre. — Marc : 14 tournées urbaines de plus, besoin de tablettes. — Admin : 2 jours-homme maximum, migration TMS d'abord. — Sonia : budget total 400 k€ pour 6 projets, ce projet 90 k€. — Décision : pilote à Nancy centre à partir du 15 septembre. — Marc liste les tournées avant le 30 juin. — Admin chiffre l'intégration avant le 5 juillet. — Paul : formation des conducteurs à planifier. — Sonia : budget validé en comité le 10 juillet. — Point ouvert : zones à faibles émissions, règles de circulation à vérifier."], "taches": ["Triez : décisions, actions, points ouverts.", "Écrivez chaque action sous la forme qui / quoi / quand.", "Rédigez le compte rendu en 10 lignes maximum.", "Écrivez l'objet de l'e-mail d'envoi.", "Précisez à qui il est envoyé (À) et en copie (Cc)."], "livrable": "Compte rendu d'une page.", "corr": {"methode": ["Trier les notes en trois catégories.", "Toute action = qui + quoi + quand.", "Décisions d'abord, actions ensuite, points ouverts à la fin.", "Envoyer sous 24 h."], "rows": [["Décision", "Pilote à Nancy centre à partir du 15 septembre"], ["Action 1", "Marc : lister les tournées urbaines avant le 30 juin"], ["Action 2", "Admin : chiffrer l'intégration avant le 5 juillet"], ["Action 3", "Sonia : faire valider le budget de 90 k€ au comité du 10 juillet"], ["Action 4", "Paul : proposer un calendrier de formation (date à fixer : à valider)"], ["Point ouvert", "Règles de circulation en zone à faibles émissions : responsable à désigner"]], "erreurs": ["Retranscrire la discussion au lieu des décisions.", "Action sans responsable ou sans date : elle ne sera pas faite.", "Envoyer le compte rendu une semaine après : la mémoire s'efface."], "modele": ["Objet : Compte rendu — Dernier kilomètre, 6 juin : pilote Nancy centre décidé", "Décision : pilote à Nancy centre à partir du 15 septembre. Budget visé : 90 k€ sur 400 k€ (6 projets).", "Actions : Marc, liste des tournées urbaines (14 de plus), avant le 30 juin. Admin, chiffrage de l'intégration (2 j-h maximum), avant le 5 juillet. Sonia, validation du budget, comité du 10 juillet. Paul, calendrier de formation des conducteurs, date à fixer.", "Point ouvert : règles en zone à faibles émissions, responsable à désigner. À : participants. Cc : directrice."], "retenir": "Un bon compte rendu se lit en 1 minute : décisions, actions (qui, quoi, quand), points ouverts."}}, "EX14": {"id": "EX14", "titre": "Écrire un ticket d'incident exploitable", "mode": "Binôme", "duree": 10, "chap": "Carnet · chapitre 4", "situation": ["Message reçu : « La synchro des tablettes ne marche plus depuis ce matin, c'est urgent, les gars sont bloqués. »", "Faits recueillis : début 6 h 40 ; 14 tablettes sur 60 touchées ; message d'erreur « 504 » ; problème sur le Wi-Fi du quai ; application version 3.2.1 ; dernier changement : mise à jour de dimanche ; les conducteurs peuvent travailler sur papier, avec 10 minutes de retard par tournée."], "taches": ["Écrivez le titre du ticket (une ligne).", "Complétez : contexte, impact, observé / attendu, étapes pour reproduire, pièces jointes.", "Calculez la part de tablettes touchées.", "Choisissez la priorité : P1 arrêt total, P2 dégradation majeure avec contournement coûteux, P3 gêne, P4 demande.", "Justifiez."], "livrable": "Un ticket complet.", "corr": {"methode": ["Titre = où + quoi + quand.", "Impact en nombre de personnes et en temps.", "Observé / attendu / reproduire.", "Priorité selon une grille écrite."], "rows": [["Titre", "Tablettes conducteurs : erreur 504 à la synchro depuis 6 h 40 (Wi-Fi du quai)"], ["Part touchée", "14 / 60 = 23 % des tablettes"], ["Impact", "14 conducteurs sur papier, environ 10 minutes de retard par tournée"], ["Observé / attendu", "Observé : erreur 504 à la synchro. Attendu : synchro en moins de 30 s"], ["À reproduire / pièces", "Ouvrir l'application v3.2.1 sur le Wi-Fi du quai, lancer la synchro ; joindre une capture de l'erreur ; changement suspect : mise à jour de dimanche"], ["Priorité", "P2 : dégradation majeure avec contournement coûteux ; pas P1 car l'activité continue"]], "erreurs": ["Titre « urgent » sans information.", "Mélanger plusieurs problèmes dans un seul ticket.", "Oublier de mentionner le dernier changement : c'est la première piste de l'équipe technique."]}}, "EX15": {"id": "EX15", "titre": "Cartographier un argument : le modèle de Toulmin", "mode": "Binôme", "duree": 12, "chap": "Carnet · chapitre 5", "situation": ["Marc affirme : « TransLor doit passer aux camions électriques pour le dernier kilomètre. »", "Éléments disponibles : 14 tournées urbaines de 80 km par jour ; autonomie annoncée de 200 km (donnée du constructeur, non mesurée) ; zones à faibles émissions en extension ; aides à l'achat de véhicules propres ; prix d'achat plus élevé qu'un diesel."], "taches": ["Identifiez l'affirmation (A), les données (D), la garantie (G) qui relie D à A, le fondement (F) de la garantie.", "Formulez la réfutation possible (R) et la réserve (Q, « sauf si… »).", "Quelle donnée est la plus fragile ?", "Reformulez l'affirmation avec un qualificatif (probablement, dans les conditions…).", "Quelle preuve supplémentaire demandez-vous avant de décider ?"], "livrable": "Un schéma de Toulmin complété.", "corr": {"methode": ["Écrire l'affirmation en une phrase.", "Lister les données vérifiables.", "Expliciter la garantie : pourquoi ces données mènent à cette affirmation.", "Chercher la réfutation avant l'adversaire."], "cols": ["Élément", "Contenu"], "widths": [1.8, 6.4], "rows": [["Affirmation", "Passer aux camions électriques pour le dernier kilomètre"], ["Données", "80 km/jour pour 14 tournées ; autonomie 200 km ; extension des zones à faibles émissions ; aides"], ["Garantie", "Si l'autonomie couvre la tournée et que les zones restreignent le diesel, l'électrique est adapté"], ["Fondement", "Mesures d'autonomie réelles (hiver, chargement) et textes sur les zones"], ["Réfutation / réserve", "Autonomie réelle plus faible en hiver ; coût d'achat ; points de recharge : sauf si le coût total est supérieur"], ["Donnée fragile", "L'autonomie de 200 km est annoncée, non mesurée"]], "erreurs": ["Prendre la donnée du constructeur pour un fait établi.", "Oublier la garantie : l'argument semble évident, mais l'adversaire la conteste.", "Ne pas prévoir de réserve : l'argument paraît absolu et se brise sur la première objection."]}}, "EX16": {"id": "EX16", "titre": "Chasser les sophismes", "mode": "Binôme", "duree": 8, "chap": "Carnet · chapitre 5", "situation": ["Six phrases entendues en réunion :", "1. « Le concurrent X a des camions électriques, donc nous devons en acheter. »", "2. « Ce consultant n'a jamais conduit un camion, ignorez son rapport. »", "3. « Si on retarde le projet d'un mois, on perdra tous nos clients. »", "4. « Soit on passe tout à l'électrique, soit on disparaît. »", "5. « Deux conducteurs se sont plaints de la tablette, donc elle ne marche pas. »", "6. « Depuis le changement de TMS, les retards ont augmenté : le TMS est en cause. »"], "taches": ["Nommez le sophisme (popularité, attaque contre la personne, pente glissante, faux dilemme, généralisation hâtive, post hoc).", "Expliquez en une phrase pourquoi le raisonnement est fragile.", "Écrivez une contre-question.", "Citez une phrase de ce type que vous avez entendue en entreprise.", "Reformulez la phrase 6 comme une hypothèse à tester."], "livrable": "Un tableau sophisme / explication / contre-question.", "corr": {"methode": ["Chercher le lien logique entre l'affirmation et la raison donnée.", "Nommer le procédé.", "Répondre par une question, pas par une accusation."], "cols": ["N°", "Sophisme", "Contre-question"], "widths": [0.5, 2.2, 5.5], "rows": [["1", "Appel à la popularité", "« Leur contexte est-il le même que le nôtre ? »"], ["2", "Attaque contre la personne", "« Quels points du rapport sont faux ? »"], ["3", "Pente glissante", "« Quelles preuves relient un mois de retard à la perte de tous les clients ? »"], ["4", "Faux dilemme", "« Existe-t-il une étape intermédiaire, comme un pilote ? »"], ["5", "Généralisation hâtive", "« Combien de tablettes sont touchées sur 60 ? »"], ["6", "Post hoc (corrélation prise pour cause)", "« Qu'a-t-il changé d'autre en même temps ? Comparons avec les mois précédents. »"]], "erreurs": ["Traiter l'interlocuteur de « sophiste » : cela devient une attaque personnelle.", "Croire qu'un argument faux oblige à rejeter la conclusion : la conclusion peut rester vraie, mais non prouvée."]}}, "EX17": {"id": "EX17", "titre": "Évaluer cinq sources", "mode": "Binôme", "duree": 15, "chap": "Carnet · chapitre 5", "situation": ["Sujet : les camions électriques en milieu urbain. Cinq sources (fictives) :", "S1 — Article de revue à comité de lecture, 2024, méthode décrite, 3 villes, limites discutées.", "S2 — Brochure commerciale d'un constructeur, 2025, chiffres sans méthode.", "S3 — Rapport d'une agence publique, 2023, mesures sur 120 véhicules, méthode publiée.", "S4 — Billet de blog anonyme, 2022, « 100 % rentable » sans source.", "S5 — Article de presse généraliste, 2025, cite uniquement S2."], "taches": ["Notez chaque source de 0 à 2 sur 6 critères : Qui ? Quand ? Pourquoi ? Sur quoi (preuves) ? Recoupé ? Reproductible ? (maximum 12).", "Seuils : 9 et plus fiable ; 5 à 8 à recouper ; 4 et moins à écarter ou à citer avec prudence.", "Classez les sources.", "Que gardez-vous pour un état de l'art ?", "Pourquoi S5 n'ajoute-t-elle rien à S2 ?"], "livrable": "Un tableau de notation et la liste des sources retenues.", "corr": {"methode": ["Qui : auteur identifié et compétent ? Quand : récent pour le sujet ? Pourquoi : informer ou vendre ?", "Sur quoi : données et méthode visibles ? Recoupé : d'autres sources concordent ? Reproductible : méthode refaisable ?", "Additionner puis appliquer les seuils."], "cols": ["Source", "Q / Q / P / S / R / R", "Total", "Décision"], "widths": [0.7, 2.4, 0.9, 4.2], "rows": [["S1", "2 / 2 / 2 / 2 / 1 / 2", "11", "Fiable : retenue"], ["S3", "2 / 1 / 2 / 2 / 1 / 2", "10", "Fiable : retenue"], ["S5", "1 / 2 / 1 / 0 / 0 / 0", "4", "À écarter : source unique, reprend S2"], ["S2", "1 / 2 / 0 / 0 / 0 / 0", "3", "Citer comme position du constructeur seulement"], ["S4", "0 / 1 / 0 / 0 / 0 / 0", "1", "Écartée"]], "erreurs": ["Croire qu'un chiffre cité plusieurs fois est vrai : S5 dépend de S2 (source circulaire).", "Rejeter une brochure commerciale : on peut la citer comme position de l'acteur.", "Retenir seulement les sources qui confirment son idée (biais de confirmation)."]}}, "EX18": {"id": "EX18", "titre": "Mini état de l'art : comparer trois solutions de verdissement", "mode": "Groupe de 3", "duree": 20, "chap": "Carnet · chapitre 5", "situation": ["Pour le dernier kilomètre, trois solutions (scores fictifs de 1 à 5, 5 = meilleur) :", "Électrique : coût 3, autonomie 2, émissions 5, disponibilité 3.", "BioGNV : coût 4, autonomie 4, émissions 4, disponibilité 3.", "HVO (biocarburant pour moteur diesel) : coût 4, autonomie 5, émissions 3, disponibilité 4.", "Pondérations de départ : coût 30 %, autonomie 25 %, émissions 25 %, disponibilité 20 %."], "taches": ["Calculez la note pondérée de chaque solution.", "Classez-les.", "Test de sensibilité : émissions 40 %, les autres 20 % chacune. Le classement change-t-il ?", "Rédigez la conclusion en 3 phrases avec un qualificatif et une réserve.", "Quelles données réelles faudrait-il collecter avant de décider ?"], "livrable": "Tableau de calcul et conclusion rédigée.", "corr": {"methode": ["Note = somme (score × poids).", "Refaire avec d'autres poids pour voir si le classement est stable.", "Conclure avec réserve : les scores sont fictifs et à sourcer."], "cols": ["Solution", "Base (30/25/25/20)", "Émissions 40 % (20/20/40/20)"], "widths": [1.6, 3.2, 3.5], "rows": [["Électrique", "0,9 + 0,5 + 1,25 + 0,6 = 3,25", "0,6 + 0,4 + 2,0 + 0,6 = 3,60"], ["BioGNV", "1,2 + 1,0 + 1,0 + 0,6 = 3,80", "0,8 + 0,8 + 1,6 + 0,6 = 3,80"], ["HVO", "1,2 + 1,25 + 0,75 + 0,8 = 4,00", "0,8 + 1,0 + 1,2 + 0,8 = 3,80"], ["Classement", "HVO > BioGNV > Électrique", "BioGNV = HVO (3,80) > Électrique (3,60)"], ["Lecture", "Le choix dépend de la pondération : les pondérations sont un argument, pas un fait", ""]], "erreurs": ["Présenter un classement sans test de sensibilité : il peut s'inverser avec d'autres poids.", "Oublier que les scores sont des données à sourcer, pas des vérités.", "Conclure sans réserve : « le HVO est le meilleur » alors que l'écart est faible."], "modele": "« Sous les pondérations actuelles, le HVO paraît la solution la plus adaptée (4,00 contre 3,80 et 3,25). Si les émissions deviennent la priorité (40 %), le HVO et le bioGNV sont à égalité (3,80). Avant de décider, il faut vérifier les scores sur des sources mesurées (autonomie réelle, disponibilité locale) ; ces notes sont fictives. »", "retenir": "Un état de l'art honnête : critères explicites, test de sensibilité, réserve, sources à vérifier."}}, "EX19": {"id": "EX19", "titre": "Synthèse du jour 1 : une situation de communication complète", "mode": "Binôme", "duree": 25, "chap": "Carnet · chapitres 2 à 4", "situation": ["Paul (DRH) écrit à Marc, copie à la directrice : « Encore un planning de formation changé sans me prévenir. Vous faites n'importe quoi à l'exploitation. »", "Faits : le planning a été modifié mardi pour absorber une absence ; Paul n'a pas été prévenu ; 4 conducteurs étaient convoqués à une formation obligatoire."], "taches": ["Quel niveau d'écoute Paul attend-il ? Écrivez une reformulation en 2 phrases.", "Formulez un feedback SBI sur le message de Paul (comportement : copie à la directrice et ton).", "Choisissez le canal pour répondre : appel ou e-mail ? Justifiez.", "Rédigez l'e-mail de confirmation en 8 lignes maximum, conclusion d'abord.", "Proposez une règle pour éviter la répétition."], "livrable": "Un appel préparé (3 phrases) et un e-mail.", "corr": {"methode": ["Écouter d'abord : reconnaître l'émotion et le fait.", "Feedback SBI sans jugement sur la personne.", "Appeler pour l'émotion, écrire pour la trace.", "Terminer par une règle ou une action datée."], "rows": [["Reformulation", "« Vous découvrez un changement qui touche une formation obligatoire, et vous n'avez pas été prévenu. C'est cela ? »"], ["SBI", "« Dans votre message de ce matin copié à la directrice, la phrase « n'importe quoi » ne m'aide pas à corriger ; j'aimerais qu'on parle d'abord des 4 conducteurs. »"], ["Canal", "Appel immédiat (émotion), puis e-mail pour confirmer la décision"], ["Action", "Marc informe Paul avant tout changement qui touche une formation (message avant 16 h la veille)"], ["Règle", "Un changement de planning de formation = information du RH en 2 heures, via un canal partagé"]], "erreurs": ["Répondre à chaud par écrit avec la directrice en copie : le conflit s'amplifie.", "S'excuser sans corriger la cause : la même situation reviendra.", "Oublier les 4 conducteurs : c'est l'impact réel."], "modele": "Objet : Planning de formation du 12 — conducteurs confirmés\n\nPaul, suite à notre échange de 10 h : les 4 conducteurs seront convoqués à la formation du jeudi 14 à 9 h ; vous recevrez désormais tout changement dans les 2 heures par message partagé. Je suis désolé de ne pas vous avoir prévenu mardi. Je vous confirme la liste avant 16 h. Marc", "retenir": "Écouter, appeler, confirmer par écrit, fixer une règle."}}, "F4": {"id": "F4", "titre": "Flash · Pyramide inversée : remettre le message dans l'ordre", "mode": "Binôme", "duree": 4, "chap": "Carnet · chapitre 4", "situation": ["Cinq phrases d'un e-mail à la directrice, mélangées :", "A. Contexte : lors du comité du 3 mars, deux options ont été discutées.", "B. Détails : option 1 coûte 40 k€, option 2 coûte 55 k€ mais réduit les retards.", "C. Je recommande l'option 2.", "D. Merci de confirmer avant jeudi 12 h.", "E. Cordialement."], "taches": ["Remettez les phrases dans l'ordre d'un message efficace.", "Justifiez en une phrase.", "Quelle phrase mettre dans l'objet ?"], "livrable": "", "corr": {"methode": ["Conclusion d'abord, action ensuite, contexte et détails après."], "rows": [["Ordre", "C, D, A, B, E"], ["Pourquoi", "La directrice lit d'abord la décision et l'échéance, puis choisit de lire le détail"], ["Objet", "« Option 2 recommandée : confirmation avant jeudi 12 h »"]], "erreurs": ["Raconter l'historique avant la conclusion."]}}, "F5": {"id": "F5", "titre": "Flash · Messagerie instantanée : vrai ou faux ?", "mode": "Solo puis voisin", "duree": 3, "chap": "Carnet · chapitre 4", "situation": ["1. Écrire « Bonjour » seul et attendre une réponse est une bonne pratique.", "2. Utiliser @tous pour une information non urgente est acceptable.", "3. Répondre dans le fil (thread) aide à garder les sujets séparés.", "4. Une décision importante prise en message privé n'a pas besoin de trace partagée.", "5. Les émojis sont acceptables selon la culture de l'équipe."], "taches": ["Répondez Vrai ou Faux.", "Corrigez les affirmations fausses.", "Écrivez une règle de messagerie pour TransLor."], "livrable": "", "corr": {"methode": ["Penser à l'autre : peut-il agir sans poser de question ?"], "rows": [["1", "Faux : « Bonjour + la question complète »"], ["2", "Faux : réserver @tous aux urgences"], ["3", "Vrai"], ["4", "Faux : consigner dans un canal ou un compte rendu"], ["5", "Vrai : se mettre d'accord sur les usages"]], "erreurs": ["Attendre le « bonjour » de l'autre avant d'écrire la question : on perd du temps à chaque échange."]}}, "F6": {"id": "F6", "titre": "Flash · Vulgariser trois phrases techniques", "mode": "Binôme", "duree": 6, "chap": "Carnet · chapitre 6", "situation": ["Traduisez pour la directrice (non technique), en une phrase, sans jargon :", "1. « Le TMS a une latence élevée aux heures de pointe. »", "2. « Nous allons segmenter le réseau en VLAN. »", "3. « Le RPO est de 4 heures. »"], "taches": ["Écrivez une phrase par traduction.", "Ajoutez une analogie pour la phrase 2.", "Testez sur votre voisin : a-t-il compris sans question ?"], "livrable": "", "corr": {"methode": ["Partir de l'enjeu de l'auditeur (retard, argent, risque).", "Remplacer le terme par ce qu'il change concrètement.", "Une analogie, pas trois."], "rows": [["1", "« Le logiciel de tournées répond lentement quand tout le monde s'y connecte vers 7 h. »"], ["2", "« Nous séparons le réseau en zones, comme des pièces avec des portes : un incident ne se propage plus partout. »"], ["3", "« Si une panne survient, nous pouvons perdre au maximum 4 heures de données. »"]], "erreurs": ["Remplacer un sigle par un autre sigle.", "Une analogie trop longue qui devient plus compliquée que le sujet."]}}, "EX20": {"id": "EX20", "titre": "Pitch de 2 minutes : le projet « dernier kilomètre »", "mode": "Groupe de 3", "duree": 30, "chap": "Carnet · chapitre 6", "situation": ["Public : la directrice de TransLor (non technique) et le comité de direction. Sujet : le projet de dernier kilomètre en ville (pilote à Nancy centre le 15 septembre, 90 k€ sur 400 k€, 14 tournées urbaines de 80 km par jour).", "Contrainte : 2 minutes, sans diapositive, un message clé.", "Organisation : 10 minutes de préparation individuelle ; 3 × (2 min de pitch + 3 min de retour) en groupe de 3."], "taches": ["Écrivez votre message clé en une phrase.", "Construisez le plan : accroche, problème, solution, preuve, appel à décision.", "Préparez une analogie et un chiffre.", "Pitchez 2 minutes (chronométrées).", "Évaluez vos deux pairs avec la grille sur 20 : accroche 3, message clé 4, structure 4, clarté 4, voix et posture 3, appel à décision 2."], "livrable": "Votre message clé et la grille de vos pairs.", "corr": {"methode": ["Message clé : une phrase que la directrice peut répéter.", "Accroche : un fait ou une scène, pas « bonjour, je vais vous parler de… ».", "Un chiffre, une analogie, une demande.", "S'entraîner à voix haute avec un chronomètre."], "cols": ["Critère", "Points", "Ce qui vaut le maximum"], "widths": [2.2, 0.9, 5.2], "rows": [["Accroche", "3", "Scène ou chiffre qui crée l'attention en 10 secondes"], ["Message clé", "4", "Une phrase claire, répétée à la fin"], ["Structure", "4", "Problème, solution, preuve, appel enchaînés sans digression"], ["Clarté / vulgarisation", "4", "Aucun jargon non expliqué ; une analogie"], ["Voix et posture", "3", "Débit calme, pauses, regard, mains visibles"], ["Appel à décision", "2", "Une demande datée et chiffrée (total : 20)"]], "erreurs": ["Lire ses notes : on perd le regard et la voix.", "Vouloir tout dire : 2 minutes = 1 message.", "Terminer par « voilà, c'est tout » au lieu d'une demande."], "modele_titre": "Exemple modèle (moins de 2 minutes)", "modele": "« Lundi, 7 h : quatorze tournées urbaines quittent Nancy, et 12 % dépassent le créneau promis à nos clients. Nos trois plus gros clients, 60 % de notre chiffre d'affaires, pénalisent les retards. Notre projet : un pilote de dernier kilomètre à Nancy centre à partir du 15 septembre, avec des véhicules propres adaptés à 80 km par jour et une alerte de retard 30 minutes avant le créneau. Pourquoi cela marche : les tournées urbaines sont courtes, l'e-commerce progresse et les zones à faibles émissions arrivent. Il demande 90 k€ sur les 400 k€ des six projets, et nous permet de mesurer avant d'étendre. Les risques : autonomie en hiver, disponibilité des véhicules ; nous les suivons avec deux indicateurs, taux de retard et kilomètres réels. Ce que je vous demande aujourd'hui : valider le pilote et ses 90 k€ au comité du 10 juillet. »", "retenir": "Accroche, problème, solution, preuve, risque, appel : une idée par phrase."}}, "EX21": {"id": "EX21", "titre": "Répondre aux objections de la directrice", "mode": "Binôme", "duree": 12, "chap": "Carnet · chapitre 6", "situation": ["Après votre pitch, la directrice objecte :", "1. « Pourquoi ne pas simplement sous-traiter le dernier kilomètre ? »", "2. « C'est trop cher. »", "3. « Et si les clients n'en veulent pas ? »"], "taches": ["Pour chaque objection, reformulez l'inquiétude derrière (1 phrase).", "Répondez avec un fait ou un chiffre (2 phrases).", "Terminez par une vérification : « Cela répond-il à votre inquiétude ? »", "Calculez la part du budget : 90 k€ sur 400 k€.", "Jouez l'échange à deux, 3 minutes, avec un observateur."], "livrable": "Trois réponses structurées.", "corr": {"methode": ["Écouter sans interrompre.", "Reformuler l'inquiétude.", "Répondre avec un fait ou un chiffre.", "Vérifier : « Cela répond-il à votre question ? »"], "cols": ["Objection", "Reformulation", "Réponse modèle"], "widths": [1.8, 2.5, 4.2], "rows": [["Sous-traiter ?", "« Vous craignez d'investir dans une activité que d'autres savent faire ? »", "« Sous-traiter limite l'investissement, mais nous perdons la relation client et les données. Le pilote nous permet de comparer le coût par livraison. »"], ["Trop cher", "« 90 k€ vous semblent élevés ? »", "« C'est 22,5 % du budget de 400 k€ (90 / 400). Le pilote limite le risque : nous mesurons avant d'étendre. »"], ["Clients ?", "« Vous voulez être sûre de la demande avant d'engager ? »", "« Le pilote se fait avec des clients volontaires ; nous fixons un seuil d'arrêt à 3 mois. Cela répond-il à votre inquiétude ? »"]], "erreurs": ["Se défendre avant d'avoir compris l'objection.", "Répondre à côté : la question pose un risque, la réponse parle d'un avantage.", "Mentir ou inventer un chiffre : « je reviens vers vous avec la source » est meilleur."]}}, "F7": {"id": "F7", "titre": "Flash · Combien coûte une réunion ?", "mode": "Binôme", "duree": 4, "chap": "Carnet · chapitre 7", "situation": ["Réunion hebdomadaire : 8 participants, 1 heure, 45 semaines par an, coût horaire chargé 32 €."], "taches": ["Calculez le coût d'une réunion et le coût annuel.", "Économie si 3 participants inutiles ne viennent plus.", "Économie si la durée passe à 30 minutes.", "Combinez les deux : coût annuel et économie."], "livrable": "", "corr": {"methode": ["Coût = participants × durée × coût horaire.", "Annuel = coût × nombre de semaines."], "rows": [["Une réunion", "8 × 1 × 32 = 256 €"], ["Par an", "256 × 45 = 11 520 €"], ["3 participants en moins", "5 × 32 × 45 = 7 200 € ; économie 4 320 €"], ["30 minutes", "8 × 0,5 × 32 × 45 = 5 760 € ; économie 5 760 €"], ["Les deux", "5 × 0,5 × 32 × 45 = 3 600 € ; économie 7 920 €"]], "erreurs": ["Compter seulement la durée et oublier le coût des participants.", "Conclure qu'il faut supprimer la réunion : l'objectif est une réunion utile, pas aucune."]}}, "EX22": {"id": "EX22", "titre": "Annoncer le report du pilote", "mode": "Binôme", "duree": 10, "chap": "Carnet · chapitre 7", "situation": ["Le pilote à Nancy centre prévu le 15 septembre est reporté de 8 semaines (nouvelle date : 10 novembre) car la livraison des véhicules est retardée. 14 tournées urbaines sont concernées.", "Publics : les conducteurs, les gestionnaires, trois clients impliqués, la directrice."], "taches": ["Identifiez les publics et ce que chacun veut savoir.", "Structure : fait, cause, impact, plan, soutien, prochain point.", "Rédigez l'annonce aux conducteurs en 6 lignes.", "Choisissez le canal et le moment pour chaque public.", "Anticipez deux questions difficiles et leurs réponses."], "livrable": "L'annonce aux conducteurs.", "corr": {"methode": ["Fait d'abord, sans enrobage.", "Cause factuelle, sans chercher de coupable.", "Impact sur le public concerné.", "Plan et prochaine information datée."], "rows": [["Directrice", "Avant tout le monde : appel, 5 minutes (décision et plan)"], ["Conducteurs", "Réunion courte puis message écrit le même jour"], ["Clients", "Appel personnalisé du responsable, puis e-mail"], ["Questions difficiles", "« Pourquoi si tard ? » : date de la notification fournisseur. « Mes tournées changent-elles ? » : non avant le 10 novembre"]], "erreurs": ["Annoncer par e-mail sans l'expliquer à l'oral : les rumeurs partent.", "Minimiser : « petit retard » pour 8 semaines.", "Promettre une date sans l'avoir confirmée avec le fournisseur."], "modele": "« Le pilote du dernier kilomètre ne démarrera pas le 15 septembre mais le 10 novembre, soit 8 semaines plus tard. La cause : la livraison des véhicules est retardée par le constructeur. Vos tournées actuelles ne changent pas avant cette date. La formation est reportée en conséquence. Je vous donne un point d'étape le 15 octobre et je reste disponible après la réunion pour vos questions. »", "retenir": "Fait, cause, impact, plan, prochain point : dans cet ordre, sans minimiser."}}, "EX23": {"id": "EX23", "titre": "Réunion tendue : exploitation contre informatique", "mode": "Groupe de 4", "duree": 12, "chap": "Carnet · chapitre 7", "situation": ["Rôles : Marc (exploitation), Admin (informatique), animateur, observateur.", "Marc : « L'informatique ne comprend rien à nos contraintes. » Admin : « Vous nous envoyez vos demandes à la dernière minute. »", "Mission de l'animateur : en 10 minutes, obtenir deux engagements (qui, quoi, quand). L'observateur remplit la grille."], "taches": ["Animateur : poser le cadre (objectif, durée, règles).", "Reformuler chaque position et séparer faits et jugements.", "Chercher un intérêt commun.", "Obtenir deux engagements datés.", "Observateur : noter les reformulations, les jugements évités, les engagements obtenus."], "livrable": "Deux engagements écrits et la grille remplie.", "corr": {"methode": ["Cadre : objectif, durée, règle de parole.", "Reformuler, puis séparer faits et jugements.", "Chercher l'intérêt commun.", "Conclure par des engagements qui / quoi / quand."], "cols": ["Moment", "Phrase d'animateur"], "widths": [1.8, 6.4], "rows": [["Cadre", "« Nous avons 10 minutes pour sortir avec deux engagements, chacun parle à son tour. »"], ["Reformuler", "« Marc, vous avez besoin d'une réponse rapide ; Admin, vous avez besoin de délais réalistes. »"], ["Faits / jugements", "« Combien de demandes sont arrivées à moins de 24 h le mois dernier ? »"], ["Intérêt commun", "« Vous voulez tous les deux des tournées sans panne. »"], ["Engagements", "Marc dépose ses demandes par ticket avant 16 h pour J+2 ; Admin répond sous 24 h avec une estimation"]], "erreurs": ["Donner raison à l'un des deux : l'animateur perd sa neutralité.", "Rester sur des jugements (« ne comprend rien ») sans mesurer.", "Terminer sans engagement daté : la tension reviendra."]}}, "EX24": {"id": "EX24", "titre": "Mon plan d'action 30-60-90 jours", "mode": "Individuel puis binôme", "duree": 15, "chap": "Carnet · chapitre 8", "situation": ["Vous avez vu écoute, affirmation, écrit, argumentation, oral et gestion de la tension. Choisissez trois compétences à progresser dans votre contexte (alternance, stage, projet)."], "taches": ["Choisissez 3 compétences.", "Pour chacune, une action à 30 jours, une à 60 jours, une à 90 jours.", "Un indicateur mesurable par action.", "Un premier pas demain (moins de 15 minutes).", "Partagez-le avec votre voisin et fixez une date de point."], "livrable": "Le plan rempli dans le carnet.", "corr": {"methode": ["Une compétence = une action observable.", "Indicateur chiffré ou daté.", "Premier pas demain : se rendre un engagement impossible à ignorer."], "cols": ["Compétence", "30 jours", "60 jours", "90 jours"], "widths": [1.7, 2.2, 2.2, 2.2], "rows": [["Écoute", "Reformuler dans 3 entretiens", "Faire une triade avec un collègue", "Recueillir un besoin et le faire valider"], ["Écrit", "Objet précis sur 100 % de mes e-mails", "Compte rendu sous 24 h", "Un ticket ou une note de synthèse relue"], ["Oral", "Pitch de 2 min devant un pair", "Prise de parole en réunion d'équipe", "Présentation à un public averti"]], "erreurs": ["Plan trop large : trois compétences, pas six.", "Aucune date de point : sans suivi, le plan s'oublie.", "Objectifs vagues : « mieux communiquer »."]}}, "F8": {"id": "F8", "titre": "Exit ticket · fin du jour 1", "mode": "Individuel", "duree": 5, "chap": "Carnet · tous chapitres", "situation": ["Sur une demi-page du carnet, en 5 minutes."], "taches": ["Une idée que je retiens du jour 1.", "Une pratique que j'applique dès demain.", "Une question ou une difficulté qui reste.", "Un exemple de TransLor qui m'a aidé."], "livrable": ""}, "F9": {"id": "F9", "titre": "Exit ticket · fin du cours", "mode": "Individuel", "duree": 5, "chap": "Carnet · tous chapitres", "situation": ["Sur une demi-page du carnet, en 5 minutes."], "taches": ["Ce que j'ai appris de plus utile.", "Ce que je fais différemment dès lundi.", "Ce qui manquait ou était de trop dans ce cours.", "Une note de 1 à 5 : utilité en entreprise."], "livrable": ""}, "F0": {"id": "F0", "titre": "Accroche · Le SMS de la directrice", "mode": "Binôme", "duree": 5, "chap": "Carnet · chapitre 1", "situation": ["La directrice envoie ce SMS à Marc à 6 h 30 : « Décale le chargement de 14 h, il est prioritaire. »", "Marc a une réunion à 7 h. Il ne peut pas la joindre avant 10 h."], "taches": ["Combien de lectures différentes du message trouvez-vous ? Au moins quatre.", "Qu'est-ce qui manque pour agir sans risque ?", "Réécrivez le SMS en une ligne."], "livrable": "", "corr": {"methode": ["Lire mot à mot : verbe, objet, moment, personne.", "Lister ce qui est implicite.", "Réécrire avec qui, quoi, quand."], "rows": [["« Décale »", "Avancer ou retarder ? De combien ?"], ["« le chargement de 14 h »", "Lequel, s'il y en a plusieurs à cette heure ?"], ["« il est prioritaire »", "Le chargement décalé, ou celui qui prend sa place ?"], ["Ce qui manque", "Nouvel horaire, raison, qui prévenir"], ["Version claire", "« Marc, avance le chargement du client A de 14 h à 12 h, il passe avant les autres. Préviens les conducteurs. »"]], "erreurs": ["Agir sans vérifier : si Marc se trompe, le retard est pour lui.", "Reprocher à la directrice : elle est pressée, la clarification est à la charge des deux."]}}}, "quiz": [{"id": "F01", "fam": "F", "famille": "Fondamentaux", "pts": 1, "q": "Dans le schéma de communication, qu'est-ce qui permet de savoir si le message a été compris ?", "options": ["Le feedback (le retour du récepteur)", "Le canal utilisé", "Le code employé", "Le bruit"], "bonne": 0, "expl": "Sans retour, l'émetteur ignore ce qui a été compris : le feedback ferme la boucle."}, {"id": "F02", "fam": "F", "famille": "Fondamentaux", "pts": 1, "q": "Que désigne le « bruit » en communication ?", "options": ["Uniquement le son ambiant", "Tout ce qui perturbe la transmission ou la compréhension", "Un message trop long", "Le canal oral"], "bonne": 1, "expl": "Le bruit peut être technique, sémantique, psychologique ou organisationnel."}, {"id": "F03", "fam": "F", "famille": "Fondamentaux", "pts": 1, "q": "Le chiffre « 93 % de non-verbal » de Mehrabian s'applique…", "options": ["à toute communication orale", "aux présentations professionnelles", "à des messages de sentiments incohérents testés en laboratoire", "aux e-mails et messages écrits"], "bonne": 2, "expl": "Les 7 / 38 / 55 % concernent des expériences très précises, pas toute la communication."}, {"id": "F04", "fam": "F", "famille": "Fondamentaux", "pts": 2, "q": "Pour un désaccord chargé d'émotion, quel enchaînement est le plus sûr ?", "options": ["Un e-mail à toute l'équipe", "Un message dans un canal public", "Attendre que cela passe", "Un appel ou une visio, puis un écrit de confirmation"], "bonne": 3, "expl": "L'oral gère l'émotion ; l'écrit garde la trace des décisions."}, {"id": "F05", "fam": "F", "famille": "Fondamentaux", "pts": 2, "q": "« Fais-le vite. » Quel élément manque surtout dans cette demande ?", "options": ["Une échéance précise et un critère de réussite", "Une formule de politesse", "Un émoji", "Une pièce jointe"], "bonne": 0, "expl": "« Vite » ne se mesure pas : date, résultat attendu, priorité."}, {"id": "F06", "fam": "F", "famille": "Fondamentaux", "pts": 2, "q": "Le paraverbal, c'est…", "options": ["les gestes et les postures", "la voix : ton, débit, volume, silences", "le choix des mots", "la mise en page d'un document"], "bonne": 1, "expl": "Verbal = les mots ; non verbal = corps ; paraverbal = voix."}, {"id": "F07", "fam": "F", "famille": "Fondamentaux", "pts": 3, "q": "Comment détecter tôt un malentendu ?", "options": ["Répéter plus fort", "Renvoyer le même message tel quel", "Faire reformuler l'essentiel par le récepteur", "Attendre le résultat final"], "bonne": 2, "expl": "La reformulation du récepteur révèle l'écart entre ce qui est dit et ce qui est compris."}, {"id": "E01", "fam": "E", "famille": "Écoute et questionnement", "pts": 1, "q": "Reformuler, c'est…", "options": ["répéter mot à mot", "donner son avis", "conclure l'entretien", "redire avec ses mots ce que l'on a compris, pour validation"], "bonne": 3, "expl": "La reformulation vérifie la compréhension sans juger."}, {"id": "E02", "fam": "E", "famille": "Écoute et questionnement", "pts": 1, "q": "Quelle question est ouverte ?", "options": ["« Comment se passe une tournée type ? »", "« Est-ce que ça se passe bien ? »", "« Vous avez fini ? »", "« C'est bien ça ? »"], "bonne": 0, "expl": "Une question ouverte appelle un développement, pas oui ou non."}, {"id": "E03", "fam": "E", "famille": "Écoute et questionnement", "pts": 1, "q": "Pourquoi éviter « Pourquoi n'avez-vous pas… ? » ?", "options": ["Elle est trop courte", "Elle est souvent perçue comme un reproche et déclenche la justification", "Elle est trop technique", "Elle est interdite par la loi"], "bonne": 1, "expl": "Mieux : « Qu'est-ce qui a empêché… ? »"}, {"id": "E04", "fam": "E", "famille": "Écoute et questionnement", "pts": 2, "q": "Dans une triade d'écoute, l'observateur…", "options": ["donne des conseils pendant l'entretien", "joue l'écouteur", "note des comportements observables sans intervenir", "ne fait que chronométrer"], "bonne": 2, "expl": "Il compte et note ; il ne juge pas."}, {"id": "E05", "fam": "E", "famille": "Écoute et questionnement", "pts": 2, "q": "« Je veux un export Excel. » Cette phrase est généralement…", "options": ["le besoin réel", "le budget disponible", "une contrainte légale", "une solution proposée : le besoin se trouve en demandant à quoi elle servira"], "bonne": 3, "expl": "On remonte du « comment » au « pourquoi » : usage, impact, critère de réussite."}, {"id": "E06", "fam": "E", "famille": "Écoute et questionnement", "pts": 2, "q": "Le silence en entretien permet…", "options": ["à l'autre d'approfondir sa pensée", "de montrer son ennui", "de gagner du temps sur la réunion", "d'éviter toute question"], "bonne": 0, "expl": "Laisser 3 secondes de blanc fait émerger ce qui n'était pas dit."}, {"id": "E07", "fam": "E", "famille": "Écoute et questionnement", "pts": 3, "q": "Écoute empathique : quelle définition est juste ?", "options": ["Être d'accord avec lui", "Comprendre le point de vue et les émotions de l'autre sans forcément les partager", "Le plaindre", "Lui donner des conseils"], "bonne": 1, "expl": "L'empathie comprend ; elle ne valide ni ne conseille."}, {"id": "A01", "fam": "A", "famille": "Affirmation et feedback", "pts": 1, "q": "Un comportement assertif consiste à…", "options": ["imposer son point de vue", "céder pour éviter le conflit", "exprimer clairement ses besoins et limites en respectant l'autre", "contourner le sujet"], "bonne": 2, "expl": "Ni passif, ni agressif, ni manipulateur."}, {"id": "A02", "fam": "A", "famille": "Affirmation et feedback", "pts": 1, "q": "Dans la méthode DESC, que veut dire le « S » ?", "options": ["Sanctionner", "Soutenir", "Synthétiser", "Spécifier le changement ou la solution demandée"], "bonne": 3, "expl": "DESC : Décrire, Exprimer, Spécifier, Conséquences."}, {"id": "A03", "fam": "A", "famille": "Affirmation et feedback", "pts": 1, "q": "Dans un feedback SBI, l'élément qui le rend utile est…", "options": ["un comportement observable", "un jugement sur la personne", "une comparaison avec un collègue", "un adjectif fort"], "bonne": 0, "expl": "SBI : Situation, Comportement, Impact. Le comportement se filme."}, {"id": "A04", "fam": "A", "famille": "Affirmation et feedback", "pts": 2, "q": "« Tu es toujours en retard. » Cette phrase est…", "options": ["un fait observable", "un jugement généralisant", "un feedback SBI", "une question ouverte"], "bonne": 1, "expl": "« Toujours » et « en retard » (un trait) ne décrivent pas une situation précise."}, {"id": "A05", "fam": "A", "famille": "Affirmation et feedback", "pts": 2, "q": "Comment dire non à une demande de la direction sans la braquer ?", "options": ["Un non sec sans explication", "Dire oui puis ne rien faire", "« Oui, si… » avec des alternatives chiffrées", "Ne pas répondre"], "bonne": 2, "expl": "On propose des options et un arbitrage."}, {"id": "A06", "fam": "A", "famille": "Affirmation et feedback", "pts": 2, "q": "Recevoir un feedback, c'est d'abord…", "options": ["se justifier", "contre-attaquer", "minimiser", "écouter, reformuler, puis choisir ce que l'on en fait"], "bonne": 3, "expl": "On peut accueillir sans être d'accord."}, {"id": "A07", "fam": "A", "famille": "Affirmation et feedback", "pts": 3, "q": "« Pas de souci, je ferai tout seul… » (avec un soupir). Quel comportement ?", "options": ["Manipulateur (passif-agressif)", "Assertif", "Agressif ouvert", "Neutre"], "bonne": 0, "expl": "Accord de façade et reproche indirect."}, {"id": "W01", "fam": "W", "famille": "Écrit professionnel", "pts": 1, "q": "La pyramide inversée dans un e-mail consiste à…", "options": ["raconter l'historique d'abord", "placer la conclusion ou la demande d'abord, puis les détails", "terminer par la demande", "supprimer les détails"], "bonne": 1, "expl": "Le lecteur pressé retient le début."}, {"id": "W02", "fam": "W", "famille": "Écrit professionnel", "pts": 1, "q": "Quel objet d'e-mail est le plus efficace ?", "options": ["« Question »", "« Urgent »", "« Décision avant jeudi : choix du transporteur »", "« Re: Re: Fwd: tournées »"], "bonne": 2, "expl": "L'objet = sujet + action attendue."}, {"id": "W03", "fam": "W", "famille": "Écrit professionnel", "pts": 1, "q": "La copie cachée (Cci) doit être utilisée…", "options": ["pour surveiller discrètement quelqu'un", "à chaque e-mail", "pour contourner la hiérarchie", "avec prudence, par exemple pour protéger des adresses externes"], "bonne": 3, "expl": "Cci n'est pas un outil de défiance."}, {"id": "W04", "fam": "W", "famille": "Écrit professionnel", "pts": 2, "q": "« Répondre à tous » est justifié lorsque…", "options": ["tous les destinataires doivent connaître la réponse", "on veut remercier tout le monde", "on veut se faire remarquer", "on ne connaît pas l'expéditeur"], "bonne": 0, "expl": "Sinon : répondre à l'expéditeur seul."}, {"id": "W05", "fam": "W", "famille": "Écrit professionnel", "pts": 2, "q": "Un bon compte rendu contient…", "options": ["la retranscription complète", "décisions, actions (qui, quoi, quand) et points ouverts", "uniquement les noms des présents", "les opinions de chacun"], "bonne": 1, "expl": "Lisible en une minute."}, {"id": "W06", "fam": "W", "famille": "Écrit professionnel", "pts": 2, "q": "Dans un ticket d'incident, les informations les plus utiles sont…", "options": ["l'opinion sur le responsable", "l'heure de déjeuner", "l'impact et les étapes pour reproduire", "une demande de réunion"], "bonne": 2, "expl": "Elles permettent de diagnostiquer sans poser de questions."}, {"id": "W07", "fam": "W", "famille": "Écrit professionnel", "pts": 3, "q": "En France, le droit à la déconnexion prévoit que…", "options": ["aucune règle n'existe", "il est interdit d'envoyer un e-mail le soir", "seuls les cadres sont concernés", "l'entreprise fixe les modalités permettant de ne pas être sollicité hors temps de travail (à vérifier)"], "bonne": 3, "expl": "Cadre : Code du travail, art. L2242-17 (à vérifier avant diffusion)."}, {"id": "G01", "fam": "G", "famille": "Argumenter et informer", "pts": 1, "q": "Dans le modèle de Toulmin, la garantie…", "options": ["relie les données à l'affirmation", "est la conclusion", "est la preuve chiffrée", "est la réfutation"], "bonne": 0, "expl": "Elle explicite pourquoi ces données mènent à cette conclusion."}, {"id": "G02", "fam": "G", "famille": "Argumenter et informer", "pts": 1, "q": "« Tout le monde le fait, donc nous devons le faire. » Quel sophisme ?", "options": ["Attaque contre la personne", "Appel à la popularité", "Pente glissante", "Faux dilemme"], "bonne": 1, "expl": "Ce que font les autres ne prouve pas que ce soit adapté à notre cas."}, {"id": "G03", "fam": "G", "famille": "Argumenter et informer", "pts": 1, "q": "Qu'est-ce qu'une source primaire ?", "options": ["Un article de presse qui cite un rapport", "Une encyclopédie", "Les données ou le témoignage d'origine, comme un rapport d'essai", "Un manuel de cours"], "bonne": 2, "expl": "On remonte à l'origine de l'information."}, {"id": "G04", "fam": "G", "famille": "Argumenter et informer", "pts": 2, "q": "Premier réflexe pour valider une affirmation chiffrée ?", "options": ["La répéter si elle est citée souvent", "Prendre la plus récente", "Demander à un collègue", "Remonter à la source d'origine et la recouper"], "bonne": 3, "expl": "Un chiffre cité plusieurs fois peut venir d'une seule source."}, {"id": "G05", "fam": "G", "famille": "Argumenter et informer", "pts": 2, "q": "Le biais de confirmation, c'est…", "options": ["chercher surtout ce qui confirme son idée de départ", "croire les experts", "douter de tout", "oublier les chiffres"], "bonne": 0, "expl": "On corrige en cherchant des arguments contraires."}, {"id": "G06", "fam": "G", "famille": "Argumenter et informer", "pts": 2, "q": "Un état de l'art, c'est…", "options": ["une liste de sources", "un panorama comparé et critique des solutions selon des critères explicites", "un résumé d'un seul article", "une opinion argumentée"], "bonne": 1, "expl": "Il compare, il ne fait pas que lister."}, {"id": "G07", "fam": "G", "famille": "Argumenter et informer", "pts": 3, "q": "Une IA générative propose une référence bibliographique. Que faire ?", "options": ["La citer telle quelle", "La citer si le titre est crédible", "Vérifier qu'elle existe réellement avant de la citer", "La supprimer sans vérifier"], "bonne": 2, "expl": "Ces outils peuvent produire des références inexistantes."}, {"id": "O01", "fam": "O", "famille": "Oral, réunions et crise", "pts": 1, "q": "Structure d'un pitch efficace ?", "options": ["Présentation, historique, détails, fin", "Conclusion, excuses, plan", "Plan, plan, plan", "Accroche, problème, solution, preuve, appel à décision"], "bonne": 3, "expl": "Un message clé et une demande."}, {"id": "O02", "fam": "O", "famille": "Oral, réunions et crise", "pts": 1, "q": "Combien de mots environ pour 2 minutes à débit calme ? (ordre de grandeur)", "options": ["250 à 300", "50", "100", "600"], "bonne": 0, "expl": "Environ 130 à 150 mots par minute ; garder de la place pour les pauses."}, {"id": "O03", "fam": "O", "famille": "Oral, réunions et crise", "pts": 1, "q": "Vulgariser, c'est d'abord…", "options": ["tout simplifier à l'extrême", "partir de l'enjeu de l'auditeur et éviter le jargon", "ajouter des sigles", "parler plus vite"], "bonne": 1, "expl": "On traduit la technique en conséquences concrètes."}, {"id": "O04", "fam": "O", "famille": "Oral, réunions et crise", "pts": 2, "q": "Face à une objection, la bonne séquence est…", "options": ["contrer immédiatement", "ignorer", "écouter, reformuler, répondre avec un fait, vérifier", "changer de sujet"], "bonne": 2, "expl": "On vérifie : « Cela répond-il à votre inquiétude ? »"}, {"id": "O05", "fam": "O", "famille": "Oral, réunions et crise", "pts": 2, "q": "Pour une réunion utile, il faut…", "options": ["inviter tout le monde", "ne rien préparer", "dépasser l'heure prévue", "un ordre du jour envoyé avant, des rôles et des décisions notées"], "bonne": 3, "expl": "Animateur, secrétaire et gardien du temps."}, {"id": "O06", "fam": "O", "famille": "Oral, réunions et crise", "pts": 2, "q": "Annoncer une mauvaise nouvelle : l'ordre le plus efficace ?", "options": ["Les faits d'abord, puis l'impact, le plan et le prochain point", "Un long contexte d'abord", "Reporter l'annonce", "Minimiser"], "bonne": 0, "expl": "Fait, cause, impact, plan, prochaine information datée."}, {"id": "O07", "fam": "O", "famille": "Oral, réunions et crise", "pts": 3, "q": "En visio, quelle pratique maintient l'attention ?", "options": ["Parler 30 minutes sans interruption", "Solliciter les participants régulièrement (question, sondage)", "Couper les caméras", "Lire ses diapositives"], "bonne": 1, "expl": "Interagir toutes les quelques minutes."}, {"id": "X01", "fam": "X", "famille": "Cas réels", "pts": 3, "q": "Tenerife, 1977 (cas à vérifier) : selon l'enquête, des messages radio ambigus ont contribué à la collision de deux avions. Quel principe aurait aidé ?", "options": ["Parler plus vite", "Réduire les échanges radio", "Confirmer chaque message par une reformulation en vocabulaire normalisé", "Utiliser des termes familiers"], "bonne": 2, "expl": "Phraséologie normalisée et confirmation (lecture en retour)."}, {"id": "X02", "fam": "X", "famille": "Cas réels", "pts": 3, "q": "Challenger, 1986 (à vérifier) : des réserves d'ingénieurs sur la température n'ont pas pesé assez dans la décision. Principe de communication ?", "options": ["Envoyer plus de diapositives", "Éviter les désaccords", "Attendre une décision orale", "Mettre en avant le message clé et la preuve, pas les noyer dans les données"], "bonne": 3, "expl": "Présenter les données de façon à rendre le risque visible."}, {"id": "X03", "fam": "X", "famille": "Cas réels", "pts": 3, "q": "Gimli Glider, 1983 (à vérifier) : une confusion d'unités (livres / kilogrammes) lors du carburant a conduit à une panne sèche. Principe ?", "options": ["Toujours écrire l'unité et faire vérifier le calcul par un second", "Utiliser un seul chiffre", "Se fier à la mémoire", "Éviter de documenter"], "bonne": 0, "expl": "Une unité manquante est un risque de malentendu."}, {"id": "X04", "fam": "X", "famille": "Cas réels", "pts": 3, "q": "Mars Climate Orbiter, 1999 (à vérifier) : deux équipes ont utilisé des unités différentes. Principe ?", "options": ["Réduire les réunions", "Documenter et valider explicitement les interfaces et les unités", "Supposer que c'est évident", "Changer d'équipe"], "bonne": 1, "expl": "Ce qui est implicite pour l'un ne l'est pas pour l'autre."}, {"id": "X05", "fam": "X", "famille": "Cas réels", "pts": 3, "q": "Columbia, 2003 (à vérifier) : l'enquête a critiqué des diapositives denses qui masquaient le risque. Quelle règle de présentation ?", "options": ["Mettre toutes les données", "Réduire la taille du texte", "Un message clé par diapositive, mis en titre", "Éviter les conclusions"], "bonne": 2, "expl": "Le titre porte la conclusion ; la diapositive la prouve."}, {"id": "X06", "fam": "X", "famille": "Cas réels", "pts": 3, "q": "Tylenol, 1982 (à vérifier) : l'entreprise a retiré rapidement les produits et communiqué ouvertement. Principe de crise ?", "options": ["Attendre l'enquête", "Nier le problème", "Limiter les informations", "Mettre la sécurité du public avant l'image, avec transparence"], "bonne": 3, "expl": "Réagir vite, être transparent, expliquer les actions."}, {"id": "X07", "fam": "X", "famille": "Cas réels", "pts": 3, "q": "Alerte missile, Hawaï, 2018 (à vérifier) : la rectification a pris environ 38 minutes. Enseignement ?", "options": ["Préparer à l'avance les messages et les canaux de rectification", "Ne jamais corriger", "Attendre une confirmation complète", "Communiquer par un seul canal"], "bonne": 0, "expl": "Un message de correction prêt gagne un temps précieux."}, {"id": "X08", "fam": "X", "famille": "Cas réels", "pts": 3, "q": "GitLab, 2017 (à vérifier) : après une suppression de données, l'équipe a publié un compte rendu détaillé. Principe ?", "options": ["Minimiser l'incident", "Transparence factuelle et retour d'expérience sans chercher de coupable", "Désigner l'auteur", "Se taire jusqu'à la fin"], "bonne": 1, "expl": "Un compte rendu clair renforce la confiance."}, {"id": "X09", "fam": "X", "famille": "Cas réels", "pts": 3, "q": "AWS S3, 2017 (à vérifier) : après une panne due à une commande mal saisie, l'éditeur a publié un post-mortem. Intérêt ?", "options": ["Éviter toute explication", "Accuser le client", "Expliquer la cause et les changements, sans chercher de coupable", "Cacher le détail technique"], "bonne": 2, "expl": "Un post-mortem construit la confiance et réduit la répétition."}, {"id": "X10", "fam": "X", "famille": "Cas réels", "pts": 3, "q": "Meta, 2021 (à vérifier) : une panne a aussi touché les outils internes de coordination. Enseignement ?", "options": ["Utiliser un seul outil", "Attendre le retour des outils", "Réduire les équipes", "Prévoir un canal de crise indépendant des systèmes touchés"], "bonne": 3, "expl": "Canal « hors bande » : SMS, téléphone, liste imprimée."}, {"id": "X11", "fam": "X", "famille": "Cas réels", "pts": 3, "q": "CrowdStrike, 2024 (à vérifier) : une mise à jour défectueuse a affecté de nombreux postes. Quel principe de communication de crise ?", "options": ["Donner vite aux clients des consignes d'action claires", "Attendre la cause exacte", "Minimiser l'ampleur", "Communiquer uniquement en privé"], "bonne": 0, "expl": "Dire ce que le client doit faire maintenant."}, {"id": "X12", "fam": "X", "famille": "Cas réels", "pts": 3, "q": "Equifax, 2017 (à vérifier) : l'incident a été annoncé plusieurs semaines après sa découverte. Principe ?", "options": ["Attendre une certitude absolue", "Informer tôt, par un canal fiable, avec des actions concrètes", "Informer uniquement la presse", "Retarder pour éviter la panique"], "bonne": 1, "expl": "Le retard et les canaux confus aggravent la perte de confiance."}], "injects": [{"id": "I1", "repere": "H+0 · 6 h 50", "titre": "Le TMS est à l'arrêt", "contexte": "60 conducteurs sont sur le quai, aucune tournée n'est affichée. Trois grands clients attendent des livraisons avant 9 h. La cause est inconnue ; l'équipe informatique est en diagnostic.", "questions": [{"q": "À qui adressez-vous un message en premier ?", "options": [["Les clients : les prévenir d'un retard", 2, "Utile, mais les conducteurs sur le quai doivent d'abord savoir quoi faire."], ["Les salariés (conducteurs et exploitation) : consigne immédiate", 3, "Ce sont eux qui doivent agir tout de suite ; ils attendent une consigne."], ["Le public sur les réseaux : prendre les devants", 0, "Rien ne justifie de s'adresser au public avant les personnes concernées."], ["La direction : l'alerter", 1, "Nécessaire en parallèle, mais la direction est déjà dans la cellule de crise."]]}, {"q": "Quel message envoyez-vous aux conducteurs ?", "options": [["« Panne du TMS. Restez au quai. Prochain point à 7 h 30 avec la marche à suivre. »", 3, "Fait, consigne et prochain point daté : le trio d'un bon message de crise."], ["« Tout va bien, on gère, continuez. »", -1, "Inexact : rien ne fonctionne. Le message perd en crédibilité."], ["« Panne du TMS. Aucune information pour l'instant. »", 1, "Honnête, mais sans consigne ni prochain point."], ["« Panne du TMS, c'est la faute de l'informatique, on attend. »", 0, "Chercher un coupable ne fait pas avancer et dresse les équipes."]]}]}, {"id": "I2", "repere": "H+3 · 9 h 50", "titre": "Une vidéo circule", "contexte": "Un conducteur a publié une vidéo : « Arrêtés depuis trois heures. » Le client le plus important appelle, inquiet. La cause est identifiée : un serveur de base de données est en défaut ; un retour est estimé à 14 h, avec incertitude.", "questions": [{"q": "Qui traitez-vous en priorité ?", "options": [["Le public sur les réseaux : démentir la vidéo", 1, "La vidéo est vraie : démentir serait faux et aggraverait la situation."], ["Les salariés : rappeler la règle de publication", 2, "À faire, sans ton punitif, mais le client attend une réponse."], ["Le client le plus important", 3, "Il est directement touché et a appelé : il passe avant la rumeur."], ["L'assureur : déclarer le sinistre", 0, "Pas urgent à cette heure."]]}, {"q": "Que dites-vous au client ?", "options": [["« Retour à la normale dans une heure. »", -1, "Promesse non fondée : si elle est fausse, la confiance s'effondre."], ["« Pas de commentaire. »", 0, "Le client conclut que vous cachez quelque chose."], ["« Retard dû à un incident technique, nous nous excusons. »", 1, "Poli mais vague : aucune information utile."], ["« Le TMS est en panne depuis 6 h 50. Livraisons de ce matin décalées. Retour estimé à 14 h, avec incertitude ; je vous confirme à 12 h et traite vos urgences par téléphone. »", 3, "Faits, estimation honnête, prochain point daté, solution pour les urgences."]]}]}, {"id": "I3", "repere": "H+24 · mercredi 7 h", "titre": "La presse appelle", "contexte": "Le service est rétabli depuis 15 h hier. Trois tournées sur 20 sont encore retardées. La presse locale demande : « Combien de colis perdus ? Des données clients ont-elles fuité ? » Vos faits : aucun colis perdu ; aucune trace de fuite à ce stade, mais l'analyse n'est pas terminée.", "questions": [{"q": "Qui répond à la presse ?", "options": [["Un porte-parole désigné, avec des éléments validés", 3, "Une voix unique évite les contradictions."], ["Personne : ne pas décrocher", 0, "Le silence laisse la place aux rumeurs."], ["Le prestataire du TMS en direct", 1, "Il peut éclairer la technique, mais la parole de l'entreprise doit être la vôtre."], ["Le premier conducteur disponible", -1, "Un conducteur n'a pas les faits validés."]]}, {"q": "Que dit-il sur les données ?", "options": [["« Aucune donnée n'a fuité. »", -1, "Non établi : si l'analyse montre le contraire, la crédibilité est perdue."], ["« C'est un acte de malveillance. »", -1, "Non établi également."], ["« Panne de 6 h 50 à 15 h ; aucun colis perdu ; l'analyse est en cours pour exclure tout impact sur les données ; résultat communiqué d'ici vendredi. »", 3, "Ce qui est sûr, ce qui est en cours, et une échéance."], ["« Nous ne communiquons pas. »", 0, "Refus pur : la presse écrira sans vos faits."]]}]}, {"id": "I4", "repere": "H+72 · vendredi", "titre": "Le client menace", "contexte": "Le prestataire du TMS reconnaît une mise à jour non testée. Le client le plus important évoque une clause de pénalité et menace de réduire ses volumes. Vous préparez votre réponse.", "questions": [{"q": "Par quel canal répondez-vous au client ?", "options": [["Un e-mail générique", 0, "Impersonnel pour un client critique."], ["Attendre qu'il relance", -1, "Il verra l'inaction comme un mépris."], ["Un communiqué public", 0, "Hors sujet : le client attend un échange direct."], ["Un appel de la directrice, puis un courrier de confirmation", 3, "Personnel, rapide, avec une trace écrite."]]}, {"q": "Quel contenu donner à cet échange ?", "options": [["Rejeter la faute sur le prestataire", -1, "Le client a contracté avec TransLor, pas avec le prestataire."], ["Causes, mesures datées (test avant mise à jour, mode de secours manuel en moins de 30 minutes) et discussion d'un geste commercial", 3, "Faits, mesures chiffrées et datées, ouverture sur la réparation."], ["Une remise immédiate, sans analyse", 0, "Une réponse commerciale sans explication ni plan."], ["Des excuses sans plan", 1, "Nécessaires, insuffisantes."]]}]}, {"id": "I5", "repere": "J+30 · retour d'expérience", "titre": "Tirer les leçons", "contexte": "Un mois après la panne, la direction veut un retour d'expérience partagé avec toute l'entreprise, et un dispositif durable.", "questions": [{"q": "Que doit contenir le retour d'expérience ?", "options": [["Les faits, les causes, ce qui a marché ou non, des actions (qui, quoi, quand), sans coupable", 3, "Un retour d'expérience utile est factuel, sans coupable, avec des actions datées."], ["Seulement les bonnes décisions", 1, "Incomplet : on apprend aussi des erreurs."], ["Rien : la page est tournée", 0, "On répétera les mêmes erreurs."], ["Le nom du responsable", -1, "La recherche de coupable bloque la remontée d'informations."]]}, {"q": "Quel dispositif de communication pérenne mettez-vous en place ?", "options": [["Un e-mail annuel de rappel", 1, "Insuffisant."], ["Un nouvel outil de messagerie", 0, "Un outil ne remplace ni les rôles ni les messages prêts."], ["Aucun dispositif", 0, "Le prochain incident repartira de zéro."], ["Un plan de crise : annuaire, canal hors bande (SMS), messages pré-rédigés, porte-parole", 3, "Prêt à l'emploi le jour où le TMS tombe."]]}]}], "publics": [["Salariés", "Conducteurs, exploitation, support"], ["Clients", "Grands comptes et clients touchés"], ["Direction", "Directrice et comité de direction"], ["Public", "Réseaux sociaux, presse locale"], ["Partenaires", "Prestataire du TMS, assureur"]], "scenario": "Mardi 6 h 50. Le logiciel de tournées (TMS) de TransLor est inaccessible. 60 conducteurs attendent sur le quai, 20 tournées doivent partir, trois grands clients attendent leurs livraisons avant 9 h. Cause inconnue. Vous êtes la cellule de communication de crise : à chaque inject, répondez en équipe (2 décisions).", "titres": [[0, "Communicant en herbe"], [12, "Chargé de communication"], [20, "Directeur de la communication"], [26, "Porte-parole de l'année"]], "familles": {"F": "Fondamentaux", "E": "Écoute et questionnement", "A": "Affirmation et feedback", "W": "Écrit professionnel", "G": "Argumenter et informer", "O": "Oral, réunions et crise", "X": "Cas réels"}};
